    def _inspect_share_with_share_id_v11225(self, share_url: str) -> Dict[str, Any]:
        identity = _share_identity(share_url)
        if not identity:
            return {"success": False, "message": "无效光鸭分享链接"}
        full_share_id, _ = identity.split("|", 1)
        list_share_ids = []
        base_share_id = full_share_id.split("_", 1)[0]
        for value in (base_share_id, full_share_id):
            if value and value not in list_share_ids:
                list_share_ids.append(value)

        client, _ = self._get_guangya_runtime()
        if not client:
            return {"success": False, "message": "光鸭云盘助手未运行或未登录"}
        token, error = self._share_access(client, share_url)
        if not token:
            return {"success": False, "message": error}

        last_error = ""
        for list_share_id in list_share_ids:
            stack: List[Tuple[str, str]] = [("", "")]
            root_ids: List[str] = []
            fingerprint_rows: List[str] = []
            legacy_fingerprint_rows: List[str] = []
            files: List[Dict[str, Any]] = []
            count = 0
            raw_key_samples: List[str] = []
            failed = False

            while stack and count < self._max_share_files:
                parent_id, parent_path = stack.pop()
                page = 1
                while count < self._max_share_files:
                    response = client._request(
                        method="POST",
                        url=f"{client.API_BASE_URL}/nd.bizuserres.s/v1/get_share_page_files_list",
                        data={
                            "shareId": list_share_id,
                            "accessToken": token,
                            "parentId": parent_id,
                            "page": page,
                            "pageSize": 100,
                            "orderBy": 0,
                            "sortType": 0,
                        },
                        need_auth=False,
                    )
                    if not self._is_success(response):
                        last_error = str(response.get("msg") or response.get("error") or "读取分享文件失败")
                        failed = True
                        break
                    raw_items = _extract_result_list(response)
                    for raw in raw_items[:4]:
                        if isinstance(raw, dict):
                            sample = ",".join(sorted(str(key) for key in raw.keys())[:24])
                            if sample and sample not in raw_key_samples:
                                raw_key_samples.append(sample)
                    for raw in raw_items:
                        item = _leaf_item_v11225(raw)
                        if not item:
                            continue
                        count += 1
                        rel_name = item.get("name") or ""
                        rel = _safe_relative_path("/".join(
                            value for value in (parent_path.strip("/"), str(rel_name).strip("/")) if value
                        ))
                        if not rel and item.get("path_hint_v11225"):
                            rel = _safe_relative_path(item.get("path_hint_v11225"))
                        fingerprint_rows.append(
                            f"{item['id']}|{rel}|{item['size']}|{int(item['is_dir'])}|{item.get('digest') or ''}"
                        )
                        legacy_fingerprint_rows.append(
                            f"{item['id']}|{item['name']}|{item['size']}|{int(item['is_dir'])}"
                        )
                        if parent_id == "":
                            root_ids.append(str(item.get("id") or ""))
                        if item["is_dir"]:
                            stack.append((item["id"], rel))
                        else:
                            files.append({**item, "relative_path": rel, "parent_path": parent_path})
                        if count >= self._max_share_files:
                            break
                    if len(raw_items) < 100:
                        break
                    page += 1
                if failed:
                    break

            if failed:
                continue
            valid_paths = [
                str(row.get("relative_path") or row.get("name") or "")
                for row in files
                if _safe_relative_path(row.get("relative_path") or row.get("name") or "")
            ]
            media_paths = [path for path in valid_paths if _is_video(path) or _is_subtitle(path)]
            if files and not valid_paths:
                last_error = "分享节点仍未返回可用文件名"
                continue

            fingerprint = hashlib.sha256("\n".join(sorted(fingerprint_rows)).encode("utf-8")).hexdigest()
            legacy_fingerprint = hashlib.sha256("\n".join(sorted(legacy_fingerprint_rows)).encode("utf-8")).hexdigest()
            result = {
                "success": True,
                "access_token": token,
                "share_id": full_share_id,
                "root_ids": [value for value in root_ids if value],
                "fingerprint": fingerprint,
                "legacy_fingerprint": legacy_fingerprint,
                "file_count": count,
                "leaf_count": len(files),
                "files": files,
                "share_id_request_v11225": list_share_id,
                "raw_key_samples_v11225": raw_key_samples[:4],
            }
            self._plugin_log(
                "INFO",
                "【光鸭转存助手】【分享叶子兼容v1.12.25】share_id=%s 补传 shareId 后重读成功：节点=%s 叶子=%s 有效路径=%s 媒体=%s 字段=%s",
                full_share_id,
                count,
                len(files),
                len(valid_paths),
                len(media_paths),
                " | ".join(raw_key_samples[:2]) or "-",
            )
            self._inspect_cache[identity] = (time.time(), result)
            return dict(result)

        return {"success": False, "message": last_error or "补传 shareId 后仍无法读取分享文件"}

    def _inspect_share(self, share_url: str) -> Dict[str, Any]:
        """分享读取：legacy 失败或叶子路径全空时，必须进入 shareId+accessToken 新协议。

        旧逻辑在 ``success=False`` 时直接 return，导致缺 shareId 的新版接口永远无法重试。
        """
        identity = _share_identity(share_url)
        result = dict(super()._inspect_share(share_url) or {})
        legacy_ok = bool(result.get("success"))
        empty_paths = legacy_ok and self._probe_has_empty_leaf_paths_v11225(result)
        need_share_id = (not legacy_ok) or empty_paths
        if not need_share_id:
            return result

        reason = "legacy_failed" if not legacy_ok else "empty_leaf_paths"
        self._plugin_log(
            "WARNING",
            "【光鸭转存助手】【分享读取】stage=list_share_files reason=%s share_id=%s "
            "legacy_success=%s leaf=%s；补传 shareId+accessToken 重试 retryable=true",
            reason,
            identity.split("|", 1)[0] if identity else "-",
            legacy_ok,
            int(result.get("leaf_count") or len(result.get("files") or [])),
        )
        if identity:
            self._inspect_cache.pop(identity, None)
        recovered = dict(self._inspect_share_with_share_id_v11225(share_url) or {})
        if recovered.get("success"):
            return recovered
        # 不能把协议兼容失败伪装成“无视频”；显式返回读取失败，下一轮仍可重试。
        return {
            "success": False,
            "message": "分享读取失败：" + str(
                recovered.get("message") or result.get("message") or "未知协议差异"
            )[:360],
            "legacy_success": legacy_ok,
            "legacy_leaf_count": int(result.get("leaf_count") or len(result.get("files") or [])),
            "retryable": True,
            "stage": "list_share_files",
            "reason": reason,
        }


__all__ = ["GuangYaShareLeafCompatV11225Mixin", "_leaf_item_v11225"]

source_store_v180:
"""多来源订阅的配置与持久化。

Magnet/ED2K 不是交给 MoviePilot 下载器的下载任务，而是光鸭云盘原生“云添加”来源。
本层只负责绑定、去重、状态持久化和用户配置；具体 resolve/create/list 调度由
multisource_v180 执行，v1.9.0 ResourceGroup 层负责同资源候选决策。
"""

from __future__ import annotations

import time
from typing import Any, Dict, List, Optional

from .source_types_v180 import (
    SOURCE_SCHEMA_VERSION,
    SOURCE_TYPES,
    normalize_source_uri,
    safe_int,
    source_identity,
)


class GuangYaSourceStoreMixin:
    """保存 Magnet/ED2K 与 MoviePilot 订阅的绑定关系。"""

    _external_auto_dispatch = True
    _source_priority = ("guangya", "magnet", "ed2k")
    _offline_poll_minutes = 2
    _offline_retry_minutes = 15
    _offline_max_attempts = 3

    def init_plugin(self, config: dict = None) -> None:
        config = dict(config or {})
        self._external_auto_dispatch = bool(config.get("external_auto_dispatch", True))

        raw_priority = config.get("source_priority") or "guangya,magnet,ed2k"
        if isinstance(raw_priority, (list, tuple)):
            tokens = [str(value).strip().lower() for value in raw_priority]
        else:
            tokens = [
                value.strip().lower()
                for value in str(raw_priority).replace("，", ",").split(",")
            ]
        ordered = []
        for value in tokens:
            if value in SOURCE_TYPES and value not in ordered:
                ordered.append(value)
        self._source_priority = tuple(ordered or ("guangya", "magnet", "ed2k"))

        self._offline_poll_minutes = max(
            1, min(safe_int(config.get("offline_poll_minutes"), 2, 1), 60)
        )
        self._offline_retry_minutes = max(
            1, min(safe_int(config.get("offline_retry_minutes"), 15, 1), 720)
        )
        self._offline_max_attempts = max(
            1, min(safe_int(config.get("offline_max_attempts"), 3, 1), 20)
        )
        self._ensure_source_store()
        super().init_plugin(config)

    def _source_store(self) -> Dict[str, Any]:
        raw = self.get_data("subscription_sources") or {}
        if not isinstance(raw, dict):
            raw = {}
        items = raw.get("items")
        if not isinstance(items, dict):
            items = {}
        return {
            "schema": SOURCE_SCHEMA_VERSION,
            "items": {
                str(key): dict(value)
                for key, value in items.items()
                if isinstance(value, dict)
            },
            "updated_at": str(raw.get("updated_at") or ""),
        }

    def _ensure_source_store(self) -> None:
        store = self._source_store()
        self._save_source_store(store)

    def _save_source_store(self, store: Dict[str, Any]) -> None:
        store = dict(store or {})
        store["schema"] = SOURCE_SCHEMA_VERSION
        store["updated_at"] = (
            self._now_text()
            if hasattr(self, "_now_text")
            else time.strftime("%Y-%m-%d %H:%M:%S")
        )
        if not isinstance(store.get("items"), dict):
            store["items"] = {}
        self.save_data("subscription_sources", store)

    def _sources_for_subscription(
        self,
        subscribe_id: int,
        *,
        enabled_only: bool = True,
    ) -> List[Dict[str, Any]]:
        sid = int(subscribe_id or 0)
        rows: List[Dict[str, Any]] = []
        for source_id, raw in self._source_store()["items"].items():
            if int(raw.get("subscribe_id") or 0) != sid:
                continue
            if enabled_only and not bool(raw.get("enabled", True)):
                continue
            row = dict(raw)
            row["id"] = str(raw.get("id") or source_id)
            rows.append(row)
        priority = {name: index for index, name in enumerate(self._source_priority)}
        rows.sort(
            key=lambda row: (
                priority.get(str(row.get("type") or ""), 99),
                str(row.get("created_at") or ""),
                str(row.get("id") or ""),
            )
        )
        return rows

    def _upsert_source(
        self,
        subscribe_id: int,
        uri: str,
        *,
        label: str = "",
        origin: str = "manual",
        enabled: bool = True,
        auto_dispatch: Optional[bool] = None,
    ) -> Dict[str, Any]:
        sid = int(subscribe_id or 0)
        subscribe = self._find_subscription(sid) if sid else None
        if not sid or not subscribe:
            raise ValueError("MoviePilot 订阅不存在")

        normalized = normalize_source_uri(uri)
        source_id = source_identity(normalized["type"], normalized["identity"], sid)
        store = self._source_store()
        previous = dict(store["items"].get(source_id) or {})
        now = self._now_text()
        row = {
            **previous,
            **normalized,
            "id": source_id,
            "subscribe_id": sid,
            "label": str(label or previous.get("label") or "").strip()[:120],
            "origin": str(origin or previous.get("origin") or "manual").strip()[:40],
            "enabled": bool(enabled),
            "state": str(previous.get("state") or "new"),
            "attempts": int(previous.get("attempts") or 0),
            "created_at": str(previous.get("created_at") or now),
            "updated_at": now,
            "last_error": str(previous.get("last_error") or ""),
            "task_id": str(previous.get("task_id") or ""),
            "task_status": previous.get("task_status"),
            "progress": int(previous.get("progress") or 0),
            "file_id": str(previous.get("file_id") or ""),
            "resolved_name": str(previous.get("resolved_name") or ""),
            "resolved_url": str(previous.get("resolved_url") or ""),
            "selected_indexes": list(previous.get("selected_indexes") or []),
            "next_retry_at": float(previous.get("next_retry_at") or 0),
            "auto_dispatch": (
                self._external_auto_dispatch
                if auto_dispatch is None
                else bool(auto_dispatch)
            ),
        }
        if not previous:
            row["state"] = "new"

        store["items"][source_id] = row
        self._save_source_store(store)

        # 外部来源一旦绑定，沿用现有固定分流硬门禁；绝不让原生 RSS/搜索重复下载。
        self._add_selected_subscription(sid, persist=True)
        self._record_route_health(
            last_source_added_at=now,
            last_source_added_type=row["type"],
            last_source_added_id=source_id,
        )
        return row

    def _update_source(self, source_id: str, **fields: Any) -> Optional[Dict[str, Any]]:
        source_id = str(source_id or "").strip()
        store = self._source_store()
        row = store["items"].get(source_id)
        if not isinstance(row, dict):
            return None
        updated = dict(row)
        updated.update(fields)
        updated["updated_at"] = self._now_text()
        store["items"][source_id] = updated
        self._save_source_store(store)
        return updated

    def _delete_source(self, source_id: str) -> bool:
        source_id = str(source_id or "").strip()
        store = self._source_store()
        row = store["items"].pop(source_id, None)
        if not row:
            return False
        self._save_source_store(store)
        # 不自动移除固定路线：该订阅可能原本就是光鸭频道路线。
        self._record_route_health(
            last_source_deleted_at=self._now_text(),
            last_source_deleted_id=source_id,
        )
        return True

    def get_form(self):
        form, defaults = super().get_form()
        try:
            content = form[0].get("content") if form else None
            if isinstance(content, list):
                content.append({
                    "component": "VCard",
                    "props": {"variant": "tonal", "class": "mt-3"},
                    "content": [
                        {
                            "component": "VCardTitle",
                            "text": "多来源订阅 · 光鸭原生云添加",
                        },
                        {
                            "component": "VCardText",
                            "text": (
                                "Magnet 与 ED2K 都直接提交光鸭云盘自带的云添加/离线任务，"
                                "不会经过 qBittorrent、Transmission、Aria2 或任何外部 Bridge。"
                                "同等满足订阅规则时默认光鸭直接转存优先，其次 Magnet，最后 ED2K。"
                            ),
                        },
                        {
                            "component": "VRow",
                            "content": [
                                {
                                    "component": "VCol",
                                    "props": {"cols": 12, "md": 3},
                                    "content": [{
                                        "component": "VSwitch",
                                        "props": {
                                            "model": "external_auto_dispatch",
                                            "label": "新增来源自动云添加",
                                        },
                                    }],
                                },
                                {
                                    "component": "VCol",
                                    "props": {"cols": 12, "md": 5},
                                    "content": [{
                                        "component": "VTextField",
                                        "props": {
                                            "model": "source_priority",
                                            "label": "来源优先级",
                                            "hint": "逗号分隔，默认 guangya,magnet,ed2k",
                                            "persistent-hint": True,
                                        },
                                    }],
                                },
                                {
                                    "component": "VCol",
                                    "props": {"cols": 6, "md": 2},
                                    "content": [{
                                        "component": "VTextField",
                                        "props": {
                                            "model": "offline_poll_minutes",
                                            "label": "任务轮询(分钟)",
                                            "type": "number",
                                        },
                                    }],
                                },
                                {
                                    "component": "VCol",
                                    "props": {"cols": 6, "md": 2},
                                    "content": [{
                                        "component": "VTextField",
                                        "props": {
                                            "model": "offline_retry_minutes",
                                            "label": "失败重试(分钟)",
                                            "type": "number",
                                        },
                                    }],
                                },
                            ],
                        },
                    ],
                })
        except Exception:
            pass

        defaults.update({
            "external_auto_dispatch": self._external_auto_dispatch,
            "source_priority": ",".join(self._source_priority),
            "offline_poll_minutes": self._offline_poll_minutes,
            "offline_retry_minutes": self._offline_retry_minutes,
            "offline_max_attempts": self._offline_max_attempts,
        })
        return form, defaults


__all__ = ["GuangYaSourceStoreMixin"]

source_types_v180:
"""Magnet/ED2K 来源规范化与稳定身份。"""

from __future__ import annotations

import base64
import hashlib
import re
from typing import Any, Dict
from urllib.parse import parse_qs, unquote, urlsplit


SOURCE_TYPES = ("guangya", "magnet", "ed2k")
SOURCE_SCHEMA_VERSION = 2
# queued 已经对应服务端 taskId，必须继续轮询而不是再次 create_task。
SOURCE_PENDING_STATES = {"new", "retry"}
SOURCE_INFLIGHT_STATES = {"dispatching", "submitted", "queued", "waiting"}
# needs_review 表示已解析资源，但集号置信度不足；必须人工确认或换候选，不能自动重试整包。
SOURCE_TERMINAL_STATES = {"completed", "failed", "disabled", "needs_review"}

_BTih_RE = re.compile(r"^(?:[0-9a-fA-F]{40}|[A-Z2-7a-z2-7]{32})$")
_ED2K_HASH_RE = re.compile(r"^[0-9a-fA-F]{32}$")


def safe_int(value: Any, default: int = 0, minimum: int = 0) -> int:
    try:
        result = int(value)
    except (TypeError, ValueError):
        return default
    return max(minimum, result)


def source_identity(source_type: str, identity: str, subscribe_id: int = 0) -> str:
    raw = f"{int(subscribe_id or 0)}|{source_type}|{identity}".encode("utf-8")
    return hashlib.sha256(raw).hexdigest()[:24]


def normalize_magnet(uri: str) -> Dict[str, Any]:
    text = str(uri or "").strip()
    if not text.lower().startswith("magnet:?"):
        raise ValueError("不是有效的 Magnet 链接")
    query = parse_qs(urlsplit(text).query, keep_blank_values=True)
    btih = ""
    for value in query.get("xt") or []:
        match = re.match(r"(?i)^urn:btih:([0-9a-z]+)$", str(value or "").strip())
        if match and _BTih_RE.fullmatch(match.group(1)):
            btih = match.group(1)
            break
    if not btih:
        raise ValueError("Magnet 缺少合法的 xt=urn:btih")
    if len(btih) == 32:
        try:
            identity = base64.b32decode(btih.upper()).hex()
        except Exception as err:
            raise ValueError("Magnet BTIH Base32 无法解码") from err
    else:
        identity = btih.lower()
    name = unquote(str((query.get("dn") or [""])[0] or "")).strip()[:300]
    size = safe_int((query.get("xl") or [0])[0], 0, 0)
    return {
        "type": "magnet",
        "uri": text,
        "identity": identity,
        "name": name,
        "size": size,
    }


def normalize_ed2k(uri: str) -> Dict[str, Any]:
    text = str(uri or "").strip()
    if not text.lower().startswith("ed2k://|file|"):
        raise ValueError("不是有效的 ED2K 文件链接")
    # ED2K 文件链接固定为 ed2k://|file|NAME|SIZE|HASH|/
    parts = text.split("|")
    if len(parts) < 6 or parts[1].lower() != "file":
        raise ValueError("ED2K 文件链接结构无效")
    name = unquote(parts[2]).strip()
    if not name:
        raise ValueError("ED2K 文件名为空")
    try:
        size = int(parts[3])
    except (TypeError, ValueError) as err:
        raise ValueError("ED2K 文件大小无效") from err
    if size <= 0:
        raise ValueError("ED2K 文件大小无效")
    digest = str(parts[4] or "").strip().lower()
    if not _ED2K_HASH_RE.fullmatch(digest):
        raise ValueError("ED2K 文件哈希无效")
    return {
        "type": "ed2k",
        "uri": text,
        "identity": digest,
        "name": name[:300],
        "size": size,
    }


def normalize_source_uri(uri: str) -> Dict[str, Any]:
    text = str(uri or "").strip()
    if text.lower().startswith("magnet:?"):
        return normalize_magnet(text)
    if text.lower().startswith("ed2k://|file|"):
        return normalize_ed2k(text)
    raise ValueError("当前仅支持 magnet:? 与 ed2k://|file| 来源")


__all__ = [
    "SOURCE_TYPES", "SOURCE_SCHEMA_VERSION", "SOURCE_PENDING_STATES",
    "SOURCE_INFLIGHT_STATES", "SOURCE_TERMINAL_STATES",
    "safe_int", "source_identity", "normalize_magnet", "normalize_ed2k",
    "normalize_source_uri",
]

stability_v1106:
"""v1.10.7 持久状态、配置稳定性与观影人工认证入口门禁。

目的不是吞异常，而是在进入旧兼容层前先把 MoviePilot 历史配置/缓存中常见的脏值规范化：
- selected_subscriptions 支持旧字符串、空值、undefined 等输入，Provider API 不再 ValueError；
- provider_timeout/result_limit、观影节点 TTL、迅雷上限等数值配置先安全归一；
- subscription_sources 中 subscribe_id/attempts/progress/next_retry_at/selected_indexes 统一清洗；
- 离线失败处理收到旧坏状态时先修复再进入原有重试状态机；
- provider_test_last 中非 dict 历史项自动剔除，状态页不再被坏缓存拖垮；
- v1.10.7 把观影人工汉字验证码/PoW 连续恢复层放到最终插件 MRO 最外侧，不改旧资源路由。

所有修复只作用于插件自己的配置/持久数据，不改变 MoviePilot 下载器、光鸭转存优先级或资源规则。
"""

from __future__ import annotations

import math
import re
from typing import Any, Dict, Iterable, List, Optional

from .gying_auth_v1107 import GuangYaGyingAuthV1107Mixin


_INT_CONFIGS = {
    "provider_timeout": (15, 5, 60),
    "provider_result_limit": (20, 1, 100),
    "viewing_node_cache_minutes": (360, 10, 1440),
    "offline_poll_minutes": (2, 1, 60),
    "offline_retry_minutes": (15, 1, 720),
    "offline_max_attempts": (3, 1, 20),
    "xunlei_flash_max_files": (80, 1, 500),
}


def safe_int_v1106(value: Any, default: int = 0, minimum: Optional[int] = None, maximum: Optional[int] = None) -> int:
    try:
        result = int(value)
    except (TypeError, ValueError):
        result = int(default)
    if minimum is not None:
        result = max(int(minimum), result)
    if maximum is not None:
        result = min(int(maximum), result)
    return result


def safe_float_v1106(value: Any, default: float = 0.0) -> float:
    try:
        result = float(value)
    except (TypeError, ValueError):
        return float(default)
    return result if math.isfinite(result) else float(default)


def selected_ids_v1106(value: Any) -> List[int]:
    if isinstance(value, str):
        raw_values: Iterable[Any] = [part for part in re.split(r"[\s,，;；]+", value.strip()) if part]
    elif isinstance(value, (list, tuple, set)):
        raw_values = value
    elif value in (None, ""):
        raw_values = []
    else:
        raw_values = [value]
    output: List[int] = []
    for raw in raw_values:
        sid = safe_int_v1106(raw, 0, 0)
        if sid > 0 and sid not in output:
            output.append(sid)
    return output


def selected_indexes_v1106(value: Any) -> List[int]:
    if isinstance(value, str):
        raw_values: Iterable[Any] = [part for part in re.split(r"[\s,，;；]+", value.strip()) if part]
    elif isinstance(value, (list, tuple, set)):
        raw_values = value
    else:
        raw_values = []
    output: List[int] = []
    for raw in raw_values:
        index = safe_int_v1106(raw, -1)
        if index >= 0 and index not in output:
            output.append(index)
    return output


def sanitize_source_row_v1106(raw: Any) -> Dict[str, Any]:
    row = dict(raw) if isinstance(raw, dict) else {}
    row["subscribe_id"] = safe_int_v1106(row.get("subscribe_id"), 0, 0)
    row["attempts"] = safe_int_v1106(row.get("attempts"), 0, 0)
    row["progress"] = safe_int_v1106(row.get("progress"), 0, 0, 100)
    row["next_retry_at"] = safe_float_v1106(row.get("next_retry_at"), 0.0)
    row["selected_indexes"] = selected_indexes_v1106(row.get("selected_indexes"))
    return row


class GuangYaStabilityV1106Mixin(GuangYaGyingAuthV1107Mixin):
    """放在插件 MRO 最外层的脏状态修复与 v1.10.7 观影认证门禁。"""

    build_id = "20260902-r18"

    def init_plugin(self, config: dict = None) -> None:
        clean = dict(config or {})
        # MoviePilot 热更新/局部保存时 config 可能不是完整配置；缺失字段必须交给下层保留，
        # 不能因为稳定层清洗而把用户现有固定转存订阅清空。
        if "selected_subscriptions" in clean:
            clean["selected_subscriptions"] = selected_ids_v1106(clean.get("selected_subscriptions"))
        for key, (default, minimum, maximum) in _INT_CONFIGS.items():
            if key in clean:
                clean[key] = safe_int_v1106(clean.get(key), default, minimum, maximum)
        super().init_plugin(clean)
        self._selected_subscriptions = selected_ids_v1106(
            getattr(self, "_selected_subscriptions", [])
        )

    def _heal_selected_subscriptions_v1106(self) -> List[int]:
        before = getattr(self, "_selected_subscriptions", [])
        safe = selected_ids_v1106(before)
        self._selected_subscriptions = safe
        if before != safe:
            try:
                updater = getattr(self, "update_config", None)
                if callable(updater):
                    updater({"selected_subscriptions": safe})
            except Exception:
                pass
        return safe

    def api_provider_test(self) -> Dict[str, Any]:
        self._heal_selected_subscriptions_v1106()
        return dict(super().api_provider_test() or {})

    def api_provider_search_selected(self) -> Dict[str, Any]:
        self._heal_selected_subscriptions_v1106()
        return dict(super().api_provider_search_selected() or {})

    def _source_store(self) -> Dict[str, Any]:
        store = dict(super()._source_store() or {})
        items = store.get("items") or {}
        clean_items: Dict[str, Dict[str, Any]] = {}
        changed = not isinstance(items, dict)
        if isinstance(items, dict):
            for source_id, raw in items.items():
                clean = sanitize_source_row_v1106(raw)
                clean_items[str(source_id)] = clean
                if not isinstance(raw, dict) or clean != raw:
                    changed = True
        store["items"] = clean_items
        if changed:
            try:
                saver = getattr(self, "_save_source_store", None)
                if callable(saver):
                    saver(store)
            except Exception:
                pass
        return store

    def _sources_for_subscription(self, subscribe_id: int, *, enabled_only: bool = True):
        sid = safe_int_v1106(subscribe_id, 0, 0)
        if sid <= 0:
            return []
        return super()._sources_for_subscription(sid, enabled_only=enabled_only)

    def _upsert_source(
        self,
        subscribe_id: int,
        uri: str,
        *,
        label: str = "",
        origin: str = "manual",
        enabled: bool = True,
        auto_dispatch: Optional[bool] = None,
        **metadata: Any,
    ):
        sid = safe_int_v1106(subscribe_id, 0, 0)
        if sid <= 0:
            raise ValueError("MoviePilot 订阅不存在")
        # 稳定层只负责 subscribe_id 清洗，必须透明转发 ResourcePlanner 后续扩展的
        # resource_group_id / target_episodes / episode_hint / source_label / message_id /
        # candidate_rank 等关键字参数，避免外层 MRO 因旧签名截断新资源合同。
        return super()._upsert_source(
            sid,
            uri,
            label=label,
            origin=origin,
            enabled=enabled,
            auto_dispatch=auto_dispatch,
            **metadata,
        )

    def _mark_offline_failure(
        self,
        source: Dict[str, Any],
        error: Exception | str,
        *,
        attempt_increment: bool = True,
    ):
        return super()._mark_offline_failure(
            sanitize_source_row_v1106(source),
            error,
            attempt_increment=attempt_increment,
        )

    def _runtime_health_rows(self, overview: Dict[str, Any]):
        try:
            raw = self.get_data("provider_test_last") or {}
            if isinstance(raw, dict):
                providers = raw.get("providers") or []
                if isinstance(providers, list):
                    clean = [dict(row) for row in providers if isinstance(row, dict)]
                    if clean != providers:
                        healed = dict(raw)
                        healed["providers"] = clean
                        try:
                            self.save_data("provider_test_last", healed)
                        except Exception:
                            pass
        except Exception:
            pass
        return super()._runtime_health_rows(overview)


__all__ = [
    "GuangYaStabilityV1106Mixin",
    "safe_int_v1106",
    "safe_float_v1106",
    "selected_ids_v1106",
    "selected_indexes_v1106",
    "sanitize_source_row_v1106",
]

status_ui_v191:
"""光鸭转存助手 v1.9.1 紧凑状态页。

旧版状态页由多个历史 mixin 的 get_page 逐层叠加，结果是正常订阅、诊断、来源任务、
路由健康和高级信息全部铺在同一页。本层作为最终展示层，不再拼接旧页面。

首页固定为 5 个区域：总览、关键指标、需要处理、正在处理、系统状态。
“等待新资源”属于正常状态，只统计数量，不进入“需要处理”；完成历史、长日志和正常订阅
也不在首页逐条展示。详细数据继续由既有 API、自检和 resource plan 提供。
"""

from __future__ import annotations

import time
from typing import Any, Dict, List

from .source_types_v180 import SOURCE_INFLIGHT_STATES, SOURCE_PENDING_STATES


_SOURCE_STATE_TEXT = {
    "new": "待处理",
    "retry": "自动重试中",
    "dispatching": "正在解析",
    "submitted": "已提交",
    "queued": "排队中",
    "waiting": "云添加中",
    "completed": "已完成",
    "failed": "失败",
    "needs_review": "待确认",
    "disabled": "已停用",
}

_TRANSFER_ACTIVE_STATES = {"submitting", "submitted", "task_confirmed", "verifying"}


class GuangYaStatusUiMixin:
    """最终状态页展示层；由 PlannerSafety 置于运行 MRO 最前端。"""

    build_id = "20260901-r3"

    @staticmethod
    def _safe_int(value: Any, default: int = 0) -> int:
        try:
            return int(value or 0)
        except (TypeError, ValueError):
            return int(default)

    def _status_source_rows_v191(self) -> List[Dict[str, Any]]:
        rows = [dict(row) for row in self._source_store()["items"].values() if isinstance(row, dict)]
        rows.sort(key=lambda row: str(row.get("updated_at") or ""), reverse=True)
        return rows

    def _status_transfer_rows_v191(self) -> List[Dict[str, Any]]:
        rows = []
        for key, raw in (self.get_data("transfer_jobs") or {}).items():
            if not isinstance(raw, dict):
                continue
            row = dict(raw)
            row["_key"] = str(key)
            rows.append(row)
        rows.sort(
            key=lambda row: str(row.get("updated_at") or row.get("time") or row.get("submitted_at") or ""),
            reverse=True,
        )
        return rows

    def _status_overview_v191(self) -> Dict[str, Any]:
        report = dict(self._build_selfcheck() or {})
        sources = self._status_source_rows_v191()
        transfer_rows = self._status_transfer_rows_v191()
        index = self.get_data("channel_index") or {}
        last_run = self.get_data("last_run") or {}
        plans = list((self.api_resource_plan().get("data") or []))

        source_summary = {
            "total": len(sources),
            "magnet": 0,
            "ed2k": 0,
            "pending": 0,
            "running": 0,
            "completed": 0,
            "failed": 0,
            "review": 0,
        }
        for row in sources:
            source_type = str(row.get("type") or "").lower()
            if source_type in {"magnet", "ed2k"}:
                source_summary[source_type] += 1
            state = str(row.get("state") or "new")
            if state in SOURCE_PENDING_STATES:
                source_summary["pending"] += 1
            elif state in SOURCE_INFLIGHT_STATES:
                source_summary["running"] += 1
            elif state == "completed":
                source_summary["completed"] += 1
            elif state == "failed":
                source_summary["failed"] += 1
            elif state == "needs_review":
                source_summary["review"] += 1

        critical_checks = [
            dict(item) for item in (report.get("checks") or [])
            if isinstance(item, dict) and item.get("critical") and not item.get("ok")
        ]
        warning_checks = [
            dict(item) for item in (report.get("checks") or [])
            if isinstance(item, dict) and not item.get("critical") and not item.get("ok")
        ]

        attention_sources = [
            row for row in sources
            if str(row.get("state") or "") in {"failed", "needs_review"}
        ]
        active_sources = [
            row for row in sources
            if str(row.get("state") or "new") in SOURCE_PENDING_STATES | SOURCE_INFLIGHT_STATES
        ]
        active_transfer_rows = [
            row for row in transfer_rows
            if str(row.get("status") or "") in _TRANSFER_ACTIVE_STATES
        ]
        failed_transfer_rows = [
            row for row in transfer_rows
            if str(row.get("status") or "") == "failed"
        ]
        unresolved_plans = [row for row in plans if row.get("uncovered")]

        attention_count = len(critical_checks) + len(attention_sources) + len(failed_transfer_rows)
        overall = "healthy"
        if critical_checks:
            overall = "error"
        elif attention_count:
            overall = "warning"

        overview = {
            "overall": overall,
            "healthy": not bool(critical_checks),
            "attention_count": attention_count,
            "selected": self._safe_int(report.get("selected"), len(self._selected_subscriptions)),
            "channel_count": len(index.get("items") or []),
            "channel_updated": str(index.get("time") or last_run.get("time") or "-"),
            "channel_errors": len(index.get("errors") or []),
            "sources": source_summary,
            "critical_checks": critical_checks,
            "warning_checks": warning_checks,
            "attention_sources": attention_sources[:8],
            "failed_transfer_rows": failed_transfer_rows[:8],
            "active_sources": active_sources[:8],
            "active_transfer_rows": active_transfer_rows[:8],
            "waiting_resource_count": len(unresolved_plans),
            "resource_plan_count": len(plans),
            "version": str(getattr(self, "plugin_version", "")),
            "build": str(getattr(self, "build_id", "")),
        }

        viewing = self.get_data("viewing_session_state") or {}
        if not isinstance(viewing, dict):
            viewing = {}
        active_node = str(viewing.get("active_node") or "")
        node_row = dict(((viewing.get("nodes") or {}).get(active_node) or {})) if active_node else {}
        overview["viewing"] = {
            "enabled": bool(getattr(self, "_viewing_enabled", False)),
            "active_node": active_node,
            "status": str(
                node_row.get("status")
                or ("waiting" if getattr(self, "_viewing_enabled", False) else "disabled")
            ),
            "verified": bool(node_row.get("verified")),
            "login_mode": str(node_row.get("login_mode") or ""),
        }

        xunlei = self.get_data("xunlei_flash_state") or {}
        items = (
            (xunlei.get("items") or {}).values()
            if isinstance(xunlei, dict) and isinstance(xunlei.get("items"), dict)
            else []
        )
        completed = failed = 0
        for raw in items:
            if not isinstance(raw, dict):
                continue
            state = str(raw.get("state") or "")
            if state == "completed":
                completed += 1
            elif state == "failed":
                failed += 1
        overview["xunlei_flash"] = {
            "enabled": bool(getattr(self, "_xunlei_flash_enabled", True)),
            "completed": completed,
            "failed": failed,
        }
        return overview

    def api_status_overview(self) -> Dict[str, Any]:
        """返回首页使用的轻量汇总，供后续独立前端复用。"""
        return {"success": True, "data": self._status_overview_v191()}

    def get_api(self) -> List[Dict[str, Any]]:
        apis = list(super().get_api() or [])
        if not any(str(item.get("path") or "") == "/status/overview" for item in apis if isinstance(item, dict)):
            apis.append({
                "path": "/status/overview",
                "endpoint": self.api_status_overview,
                "methods": ["GET"],
                "summary": "读取紧凑状态页汇总",
            })
        return apis

    @staticmethod
    def _metric(title: str, value: str, *, alert_type: str = "info", subtitle: str = "") -> Dict[str, Any]:
        text = str(value)
        if subtitle:
            text += f"\n{subtitle}"
        return {
            "component": "VCol",
            "props": {"cols": 6, "md": 3},
            "content": [{
                "component": "VAlert",
                "props": {
                    "type": alert_type,
                    "variant": "tonal",
                    "density": "compact",
                    "title": title,
                    "text": text,
                },
            }],
        }

    def _source_title(self, row: Dict[str, Any]) -> str:
        sid = self._safe_int(row.get("subscribe_id"))
        subscribe = self._find_subscription(sid) if sid else None
        name = str(getattr(subscribe, "name", "") or row.get("resolved_name") or row.get("name") or "未命名资源")
        source_type = str(row.get("type") or "source").upper()
        return f"{source_type} · {name}"

    def _transfer_title(self, row: Dict[str, Any]) -> str:
        sid = self._safe_int(row.get("subscribe_id") or row.get("sid"))
        subscribe = self._find_subscription(sid) if sid else None
        name = str(getattr(subscribe, "name", "") or row.get("name") or "光鸭转存任务")
        return f"光鸭转存 · {name}"

    def _source_trace(self, row: Dict[str, Any]) -> str:
        source_id = str(row.get("id") or "").strip()
        task_id = str(row.get("task_id") or "").strip()
        trace = f"追踪 source #{source_id[:16] or '-'}"
        if task_id:
            trace += f" · task {task_id[:20]}"
        return trace

    @staticmethod
    def _source_action_hint(state: str, row: Dict[str, Any] | None = None) -> str:
        error = str((row or {}).get("last_error") or "")
        if state == "needs_review" and "REMOTE_VERIFY_TIMEOUT" in error:
            return "建议：先刷新云任务并确认目标目录/媒体库；若仍缺失，可让后续候选继续或手动重试该来源。"
        if state == "needs_review":
            return "建议：核对集号后再执行来源重试。"
        if state == "failed":
            return "建议：先刷新云任务确认最新状态，再执行来源重试。"
        return ""

    def _attention_cards(self, overview: Dict[str, Any]) -> List[Dict[str, Any]]:
        cards: List[Dict[str, Any]] = []
        for item in overview.get("critical_checks") or []:
            cards.append({
                "component": "VAlert",
                "props": {
                    "type": "error",
                    "variant": "tonal",
                    "density": "compact",
                    "class": "mb-2",
                    "title": str(item.get("label") or "关键检查失败"),
                    "text": str(item.get("detail") or "需要检查插件运行状态"),
                },
            })

        for row in overview.get("attention_sources") or []:
            state = str(row.get("state") or "")
            error = str(row.get("last_error") or "")
            detail = error or ("集号置信度不足，已停止自动拆包" if state == "needs_review" else "云添加任务失败")
            hint = self._source_action_hint(state, row)
            text = f"{_SOURCE_STATE_TEXT.get(state, state)} · {detail}\n（{self._source_trace(row)}）"
            if hint:
                text += f"\n{hint}"
            cards.append({
                "component": "VAlert",
                "props": {
                    "type": "warning" if state == "needs_review" else "error",
                    "variant": "tonal",
                    "density": "compact",
                    "class": "mb-2",
                    "title": self._source_title(row),
                    "text": text,
                },
            })

        for row in overview.get("failed_transfer_rows") or []:
            if len(cards) >= 8:
                break
            error = str(row.get("error") or row.get("message") or "转存任务失败")[:300]
            cards.append({
                "component": "VAlert",
                "props": {
                    "type": "error",
                    "variant": "tonal",
                    "density": "compact",
                    "class": "mb-2",
                    "title": self._transfer_title(row),
                    "text": error,
                },
            })
        return cards[:8]

    def _active_cards(self, overview: Dict[str, Any]) -> List[Dict[str, Any]]:
        cards: List[Dict[str, Any]] = []

        for row in overview.get("active_transfer_rows") or []:
            cards.append({
                "component": "VAlert",
                "props": {
                    "type": "info",
                    "variant": "tonal",
                    "density": "compact",
                    "class": "mb-2",
                    "title": self._transfer_title(row),
                    "text": "已提交到光鸭，等待目标文件落盘确认",
                },
            })
            if len(cards) >= 6:
                return cards

        for row in overview.get("active_sources") or []:
            state = str(row.get("state") or "new")
            progress = max(0, min(100, self._safe_int(row.get("progress"))))
            episodes = row.get("resolved_episodes") or row.get("target_episodes") or []
            episode_text = ", ".join(f"E{self._safe_int(value):02d}" for value in episodes[:12])
            error = str(row.get("last_error") or "")
            if state == "waiting" and error.startswith("PENDING_VERIFY:"):
                try:
                    since = float(row.get("pending_verify_since") or 0)
                except (TypeError, ValueError):
                    since = 0.0
                waited = max(0, int(time.time() - since)) if since > 0 else 0
                if waited >= 60:
                    wait_text = f" · 已等待 {waited // 60} 分钟"
                else:
                    wait_text = " · 刚进入核验"
                detail = f"远端任务已完成，正在核验正片{wait_text}"
            else:
                detail = f"{_SOURCE_STATE_TEXT.get(state, state)} · {progress}%"
            if episode_text:
                detail += f" · {episode_text}"
            detail += f"\n（{self._source_trace(row)}）"
            cards.append({
                "component": "VAlert",
                "props": {
                    "type": "info" if state in SOURCE_INFLIGHT_STATES else "warning",
                    "variant": "tonal",
                    "density": "compact",
                    "class": "mb-2",
                    "title": self._source_title(row),
                    "text": detail,
                },
            })
            if len(cards) >= 6:
                break
        return cards

    def get_page(self):
        """返回单屏状态页，不再调用 super().get_page 拼接历史诊断卡。"""
        overview = self._status_overview_v191()
        sources = overview["sources"]
        viewing = dict(overview.get("viewing") or {})
        xunlei = dict(overview.get("xunlei_flash") or {})
        active_node = str(viewing.get("active_node") or "-")
