                            "props": {"size": "small", "variant": "outlined", "prepend-icon": "mdi-cloud-sync-outline"},
                            "text": "刷新云任务",
                            "events": {"click": {"api": "plugin/GuangYaTransferAssistant/offline/refresh", "method": "post"}},
                        },
                        {
                            "component": "VBtn",
